parameters.jsCode:
// Triage complaint and determine urgency routing
const body = $input.first().json.body || $input.first().json;

const priority = body.priority || "high";
const category = body.category || "general_complaint";
const guestName = body.guest_name || "Valued Guest";
const inquiry = body.inquiry || body.inquiry_text || "";

const isUrgent = priority.toLowerCase() === "urgent" || inquiry.toLowerCase().includes("emergency") || inquiry.toLowerCase().includes("twice");

return [{
  json: {
    escalation_id: body.escalation_id || null,
    conversation_id: body.conversation_id || null,
    guest_name: guestName,
    guest_email: body.guest_email || "support@azurehotel.demo",
    category: category,
    priority: isUrgent ? "urgent" : priority,
    reason: body.reason || "Complaint escalated via automated workflow.",
    inquiry_text: inquiry,
    triaged_at: new Date().toISOString()
  }
}];

